1	//! Вердикт по сетке форм отскока (B5, В-58 → В-62) — читает артефакты
2	//! `lob bounce-grid` (`rounds.csv`, `forms.csv`) и считает по контракту
3	//! BUSINESS-TASK §6–7 с поправками аудита 18.09 (K2, K3, K4):
4	//!
5	//! - **полная сетка** В-62 — декартово произведение множителей стопа, тейка и
6	//!   `DEADLINE_SECS` (имя формы `<стоп>-<тейк>-<H>`, В-65), и одинаковое число касаний
7	//!   (`n_signals + n_skipped`: у формы, которую не для всех касаний построить,
8	//!   сигналов меньше, касания те же) у всех форм на каждой паре (символ, сутки) — иначе отказ,
9	//!   не «вердикт по части»;
10	//! - по форме — все наблюдения сигналов (`FillObservation`: круг с `net_bps`
11	//!   или промах с нулём), **нижняя граница интервала `net_fill`** — тот же
12	//!   `costs::net_fill_interval` (wild cluster bootstrap-t, кластер — сутки,
13	//!   Decision 9), что у `lob backtest`; кластер суток общий для всех символов
14	//!   (режим дня один на рынок — консервативно);
15	//! - `DSR` лучшей формы по числу испытаний **этой** процедуры из `runs.csv`
16	//!   (строки `bounce_form`), рядом — по всему журналу;
17	//! - **PBO и CPCV** по матрице «форма × сутки» (ячейка — `net_fill` формы за
18	//!   сутки: сумма `net` кругов на число сигналов), теми же оценщиками и
19	//!   параметрами, что у `lob shortlist` (`REPORT_PBO_PARTITIONS`,
20	//!   `REPORT_CPCV_PARAMS`, правило отбора «лучший по среднему на IS-сутках»);
21	//! - **гейты §7**: `n ≥ CONFIRM_MIN_N` кругов и `G ≥ G_MIN` суток с кругами у
22	//!   лучшей формы — иначе итог «мало данных», а не вердикт; при гейтах —
23	//!   «красный» (нижняя граница ≤ 0 или `DSR < DSR_TARGET`), «зелёный без
24	//!   ёмкости» (нижняя граница > 0, точка < `GREEN_NET_BPS`), «зелёный».
25	//!
26	//! Деления на разведочную/подтверждающую выборки нет (решение владельца
27	//! 2026-09-17, В-58) — это записано в шапке артефакта: вердикт означает «на
28	//! всех записанных сутках», а не «подтверждено на отложенных».
29	//!
30	//! Лучшая форма выбирается по **точке** `net_fill` (правило отбора то же, что
31	//! у CPCV: среднее), вердикт — по её интервалу; так отбор и проверка разведены.
32	
33	use std::collections::{BTreeMap, BTreeSet};
34	use std::io::Write as _;
35	use std::path::{Path, PathBuf};
36	
37	use anyhow::Context as _;
38	use clap::Args;
39	
40	use crate::lob::costs::{net_fill_interval, FillObservation, NetFillInterval, GREEN_NET_BPS};
41	use crate::lob::final_metrics::{
42	    self, CpcvParams, DSR_TARGET, REPORT_CPCV_PARAMS, REPORT_PBO_PARTITIONS,
43	};
44	use crate::lob::runs::{self, BOUNCE_TRIAL_PREFIX};
45	use crate::stats::{BOOTSTRAP_REPLICATIONS, GATE_ALPHA, G_MIN};
46	
47	use super::backtest::{EntryForm, EntryTtl, StopForm, TakeForm, SINGLE_ENTRY_LABEL};
48	use super::shortlist::{select_best_mean_net, CPCV_SELECTION_RULE};
49	use crate::lob::shortlist::CONFIRM_MIN_N;
50	
51	/// Дедлайны сетки В-58, секунды (В-62: они же — окна `σ_H` в `touches`).
52	pub const DEADLINE_SECS: [u64; 4] = [60, 600, 3600, 7200];
53	/// Все разрешённые дедлайны: В-58 плюс 30 мин и 4 ч (S8 плана по сторонам,
54	/// предрегистрация 20.09: у лонгов 60 с / 10 мин на тех же сигналах −$103 /
55	/// −$65, час +$120, два часа +$111 — ось «удержание» нужно дотянуть). Сетка
56	/// задаёт свой набор `--deadline-secs` из этого списка; чужое число — отказ.
57	pub const DEADLINE_SECS_ALLOWED: [u64; 6] = [60, 600, 1800, 3600, 7200, 14400];
58	/// Причины выхода в порядке колонок артефакта.
59	pub const EXIT_REASONS: [&str; 9] = [
60	    "stop",
61	    "take",
62	    "trail",
63	    "deadline",
64	    "early",
65	    "horizon",
66	    "eaten",
67	    "eaten_by_trades",
68	    "wall_gone",
69	];
70	
71	/// Имя колонки артефакта вердикта для причины выхода: у `deadline` она
72	/// исторически `timeout` (`n_timeout`/`share_timeout`), у остальных — само
73	/// имя причины. Одна функция на обе оси колонок (`n_*` и `share_*`), чтобы
74	/// новая причина не попала в чужую колонку молчаливым `_ =>` (умолчание
75	/// прежнего кода отдавало `n_horizon` всякому неизвестному имени).
76	fn exit_column(reason: &str) -> &'static str {
77	    match reason {
78	        "deadline" => "timeout",
79	        "eaten" => "eaten",
80	        "eaten_by_trades" => "eaten_by_trades",
81	        "wall_gone" => "wall_gone",
82	        // Прежние имена причин — как в самих формах (stop/take/trail/early/horizon).
83	        "stop" => "stop",
84	        "take" => "take",
85	        "trail" => "trail",
86	        "early" => "early",
87	        _ => "horizon",
88	    }
89	}
90	
91	/// Размер полной сетки по её же именам (В-62/В-65/В-74/F6): формы стопа ×
92	/// формы тейка × дедлайны × формы входа × режимы срока жизни входа × формы
93	/// выхода, встреченные в именах (все из `DEADLINE_SECS_ALLOWED`). Сетка задана
94	/// именами владельца, не константой, и её
95	/// полнота проверяется как декартово произведение осей, встреченных в
96	/// именах форм: набор `{before-1to1-60, at-1to1-60}` без `before-1to1-600` —
97	/// не сетка. Оси названы только у форм F6/F5: у трёхпольных имён вход —
98	/// `single@fr`, срока жизни нет (`touch`), выхода нет (`none`) — прежде числа
99	/// и имена не менялись.
100	pub fn grid_size_from_labels<'a>(
101	    labels: impl IntoIterator<Item = &'a str>,
102	) -> anyhow::Result<usize> {
103	    let mut entries: BTreeSet<String> = BTreeSet::new();
104	    let mut stops: BTreeSet<String> = BTreeSet::new();
105	    let mut takes: BTreeSet<String> = BTreeSet::new();
106	    let mut deadlines: BTreeSet<u64> = BTreeSet::new();
107	    let mut ttls: BTreeSet<String> = BTreeSet::new();
108	    let mut exits: BTreeSet<String> = BTreeSet::new();
109	    let mut earlies: BTreeSet<String> = BTreeSet::new();
110	    for label in labels {
111	        let parts = parse_form_fields(label)?;
112	        entries.insert(parts.entry);
113	        stops.insert(parts.stop);
114	        takes.insert(parts.take);
115	        deadlines.insert(parts.deadline_secs);
116	        ttls.insert(parts.ttl.unwrap_or_else(|| TTL_NONE.to_string()));
117	        exits.insert(parts.exit.unwrap_or_else(|| EXIT_NONE.to_string()));
118	        earlies.insert(parts.early.unwrap_or_else(|| EARLY_NONE.to_string()));
119	    }
120	    Ok(entries.len()
121	        * stops.len()
122	        * takes.len()
123	        * deadlines.len()
124	        * ttls.len()
125	        * exits.len()
126	        * earlies.len())
127	}
128	
129	/// Метка оси «срока жизни входа нет» (прежний режим `touch`, F5, В-74).
130	const TTL_NONE: &str = "touch";
131	/// Метка оси «выход прежний» (нет ключа `--exit-form`, F7/F8).
132	const EXIT_NONE: &str = "none";
133	/// Метка оси «выхода по прилипанию нет» (нет ключа `--early-exit-secs`, В-85).
134	const EARLY_NONE: &str = "off";
135	
136	/// Имя формы: `<стоп>-<тейк>-<H>` — имена `StopForm::label`/`TakeForm::label`
137	/// (`before`, `pct1`, `s1` …; `1to1`, `t2`) и дедлайн в секундах из `DEADLINE_SECS`.
138	/// Прежняя (трёхпольная) запись: вход у неё неявный — `single@fr`.
139	pub fn form_label(stop: &str, take: &str, deadline_secs: u64) -> String {
140	    format!("{stop}-{take}-{deadline_secs}")
141	}
142	
143	/// Имя формы с входом (F6, В-73): `<вход>-<стоп>-<тейк>-<H>`; у прежнего
144	/// входа (`single@fr`) имя остаётся трёхпольным — на этом стоит гейт «те же
145	/// круги» (прежние `rounds.csv`/`forms.csv` байт в байт). Суффиксы F5/F7
146	/// (`-ttl<значение>`, `-<выход>`) дописывает вызывающий: вход стоит первым, а
147	/// `parse_form_fields` читает хвостовые поля по префиксам.
148	pub fn form_label_with_entry(entry: &str, stop: &str, take: &str, deadline_secs: u64) -> String {
149	    if entry == SINGLE_ENTRY_LABEL {
150	        form_label(stop, take, deadline_secs)
151	    } else {
152	        format!("{entry}-{stop}-{take}-{deadline_secs}")
153	    }
154	}
155	
156	/// Разобранные поля имени формы (F6): вход, стоп, тейк, дедлайн и
157	/// необязательные срок жизни входа (F5) и выход (F7). Трёхпольные имена
158	/// читаются как `single@fr-…` — обратная совместимость вердикта.
159	#[derive(Debug, Clone, PartialEq, Eq)]
160	pub struct FormFields {
161	    pub entry: String,
162	    pub stop: String,
163	    pub take: String,
164	    pub deadline_secs: u64,
165	    /// Значение `-ttl<…>`: `touch` | `wall` | секунды (F5, В-74); `None` —
166	    /// поля в имени нет.
167	    pub ttl: Option<String>,
168	    /// Значение поля выхода (F7/F8, например `eat50`); `None` — поля нет.
169	    pub exit: Option<String>,
170	    /// Секунды выхода по «прилипанию» (`-early<x>`, В-85); `None` — поля нет.
171	    pub early: Option<String>,
172	}
173	
174	#[derive(Debug, Args)]
175	pub struct BounceVerdictArgs {
176	    /// Каталог `lob bounce-grid` с `rounds.csv` и `forms.csv`.
177	    #[arg(long)]
178	    pub grid_dir: PathBuf,
179	    /// Журнал испытаний (`docs/plan/runs.csv`).
180	    #[arg(long)]
181	    pub runs_csv: PathBuf,
182	    /// Артефакт вердикта (CSV с шапкой `#`).
183	    #[arg(long)]
184	    pub out: PathBuf,
185	    /// Дописать строки испытаний `bounce_form:<форма>` в журнал перед вердиктом.
186	    #[arg(long, default_value_t = false)]
187	    pub log_trials: bool,
188	}
189	
190	/// Итог по одной форме.
191	#[derive(Debug, Clone, PartialEq)]
192	pub struct FormVerdict {
193	    pub form: String,
194	    /// Имена форм стопа и тейка (В-65).
195	    pub stop: String,
196	    pub take: String,
197	    pub deadline_secs: u64,
198	    /// Сигналов (касаний) всего по всем символам и суткам.
199	    pub n_signals: u64,
200	    /// Кругов (исполненных сделок).
201	    pub n_fills: u64,
202	    /// Суток, в которых у формы был хотя бы один круг.
203	    pub days_with_fills: usize,
204	    /// Единица кластера интервала (В-60): `day` при ≥ `G_MIN` сутках в сетке,
205	    /// иначе `hour` — вердикт возможен по одним суткам.
206	    pub cluster_unit: &'static str,
207	    /// Кластеров (суток или часов) с хотя бы одним кругом.
208	    pub clusters_with_fills: usize,
209	    /// Точка и нижняя граница интервала `net_fill` (bps на сигнал).
210	    pub interval: Option<NetFillInterval>,
211	    /// Среднее `net` по кругам (bps на круг) и Шарп ряда кругов.
212	    pub net_per_fill_bps: Option<f64>,
213	    pub sharpe: Option<f64>,
214	    pub exits: [u64; EXIT_REASONS.len()],
215	    /// Ряд `net` кругов — вход DSR.
216	    pub returns: Vec<f64>,
217	}
218	
219	impl FormVerdict {
220	    pub fn exits_of(&self, reason: &str) -> u64 {
221	        EXIT_REASONS
222	            .iter()
223	            .position(|r| *r == reason)
224	            .map(|i| self.exits[i])
225	            .unwrap_or(0)
226	    }
227	
228	    pub fn share_of(&self, reason: &str) -> Option<f64> {
229	        if self.n_fills == 0 {
230	            return None;
231	        }
232	        Some(self.exits_of(reason) as f64 / crate::stats::count_f64_u64(self.n_fills))
233	    }
234	}
235	
236	/// Итог §7 для лучшей формы.
237	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
238	pub enum Verdict {
239	    /// Гейты `n ≥ CONFIRM_MIN_N`, `G ≥ G_MIN` не пройдены — вердикта нет.
240	    NotEnoughData,
241	    /// Нижняя граница интервала ≤ 0 или `DSR < DSR_TARGET`.
242	    Red,
243	    /// Нижняя граница > 0 и `DSR ≥ DSR_TARGET`, но точка < `GREEN_NET_BPS`.
244	    GreenNoCapacity,
245	    /// Нижняя граница > 0, `DSR ≥ DSR_TARGET`, точка ≥ `GREEN_NET_BPS`.
246	    Green,
247	}
248	
249	impl Verdict {
250	    pub fn label(self) -> &'static str {
251	        match self {
252	            Self::NotEnoughData => "мало данных",
253	            Self::Red => "красный",
254	            Self::GreenNoCapacity => "зелёный без ёмкости",
255	            Self::Green => "зелёный",
256	        }
257	    }
258	}
259	
260	#[derive(Debug, Clone)]
261	pub struct BounceVerdictSummary {
262	    pub forms: usize,
263	    pub symbols: usize,
264	    pub days: usize,
265	    pub trials: usize,
266	    pub journal_trials: usize,
267	    pub best_form: String,
268	    pub best_n_fills: u64,
269	    pub best_days: usize,
270	    pub best_point_bps: Option<f64>,
271	    pub best_lower_bps: Option<f64>,
272	    pub dsr: Option<f64>,
273	    pub dsr_at_journal_trials: Option<f64>,
274	    pub required_sharpe: Option<f64>,
275	    pub pbo: Option<f64>,
276	    pub cpcv: Option<f64>,
277	    pub verdict: Verdict,
278	    pub out: PathBuf,
279	}
