281	/// Разбор имени формы `<стоп>-<тейк>-<H>` (В-65) — прежний вид без входа:
282	/// формы — через `StopForm::parse`/`TakeForm::parse` (они же проверяют
283	/// каноничность), дедлайн — из `DEADLINE_SECS`. Имена F5/F6 с суффиксом
284	/// (`-ttl<…>`) и с полем входа читаются `parse_form_fields`; здесь остаётся
285	/// тройка вердикта — стоп, тейк, дедлайн — какой её читали вызывающие до F6.
286	pub fn parse_form(label: &str) -> anyhow::Result<(String, String, u64)> {
287	    let parts = parse_form_fields(label)?;
288	    Ok((parts.stop, parts.take, parts.deadline_secs))
289	}
290	
291	/// Разбор имени формы целиком (F6, В-73 + F5, В-74): `<вход>-<стоп>-<тейк>-<H>`
292	/// с необязательными хвостовыми полями `-ttl<…>` (срок жизни входа; `wall`,
293	/// `touch` или секунды) и `-<выход>` (F7/F8), в любом порядке. Прежние
294	/// трёхпольные имена (`<стоп>-<тейк>-<H>`) читаются как `single@fr-…` —
295	/// обратная совместимость вердикта; вход проверяется `EntryForm::parse` (он же
296	/// канонизирует имя), стоп/тейк — своими `parse`, дедлайн — из
297	/// `DEADLINE_SECS_ALLOWED`.
298	pub fn parse_form_fields(label: &str) -> anyhow::Result<FormFields> {
299	    let parts: Vec<&str> = label.split('-').collect();
300	    anyhow::ensure!(
301	        parts.len() >= 3 && parts.len() <= 7,
302	        "{label}: имя формы — <вход>-<стоп>-<тейк>-<дедлайн с>[-ttl<режим>][-<выход>] (`pct2-1to1-3600`, `ladder3x2..10-pct2-1to1-3600-ttl60`)"
303	    );
304	    // Вход: четвёртый сегмент — вход только тогда, когда разбирается как
305	    // `EntryForm` (трёхпольное имя — `single@fr`).
306	    let (entry, rest) = if parts.len() >= 4 && EntryForm::parse(parts[0]).is_ok() {
307	        (parts[0].to_string(), &parts[1..])
308	    } else {
309	        (SINGLE_ENTRY_LABEL.to_string(), &parts[..])
310	    };
311	    anyhow::ensure!(
312	        rest.len() >= 3,
313	        "{label}: имя формы — <вход>-<стоп>-<тейк>-<дедлайн с>[-ttl<режим>][-<выход>]"
314	    );
315	    let stop = StopForm::parse(rest[0]).map_err(|e| anyhow::anyhow!("{label}: {e}"))?;
316	    let take = TakeForm::parse(rest[1]).map_err(|e| anyhow::anyhow!("{label}: {e}"))?;
317	    let deadline_secs: u64 = rest[2]
318	        .parse()
319	        .map_err(|_| anyhow::anyhow!("{label}: дедлайн {} не число секунд", rest[2]))?;
320	    anyhow::ensure!(
321	        DEADLINE_SECS_ALLOWED.contains(&deadline_secs),
322	        "{label}: дедлайн {deadline_secs} с вне разрешённых {DEADLINE_SECS_ALLOWED:?}"
323	    );
324	    // Хвостовые поля: `ttl<…>` — срок жизни входа (F5, В-74), остальное —
325	    // поле выхода (F7/F8). Каждое не больше одного раза.
326	    let mut ttl: Option<String> = None;
327	    let mut exit: Option<String> = None;
328	    let mut early: Option<String> = None;
329	    for tail in &rest[3..] {
330	        if let Some(v) = tail.strip_prefix("early") {
331	            anyhow::ensure!(
332	                early.is_none() && !v.is_empty(),
333	                "{label}: поле выхода по прилипанию — одно (`-early<секунды>`)"
334	            );
335	            let x: i64 = v
336	                .parse()
337	                .map_err(|_| anyhow::anyhow!("{label}: -early{v}: не целые секунды"))?;
338	            crate::commands::lob::backtest::early_exit_ns_from_secs(Some(x))
339	                .map_err(|e| anyhow::anyhow!("{label}: {e}"))?;
340	            early = Some(v.to_string());
341	        } else if let Some(v) = tail.strip_prefix("ttl") {
342	            anyhow::ensure!(
343	                ttl.is_none() && !v.is_empty(),
344	                "{label}: поле срока жизни входа — одно (`-ttl<touch|wall|секунды>`)"
345	            );
346	            parse_form_ttl(label, v)?;
347	            ttl = Some(v.to_string());
348	        } else {
349	            anyhow::ensure!(
350	                exit.is_none() && !tail.is_empty(),
351	                "{label}: поле выхода — одно (F7/F8)"
352	            );
353	            parse_form_exit(label, tail)?;
354	            exit = Some((*tail).to_string());
355	        }
356	    }
357	    Ok(FormFields {
358	        entry,
359	        stop: stop.label(),
360	        take: take.label(),
361	        deadline_secs,
362	        ttl,
363	        exit,
364	        early,
365	    })
366	}
