368	/// Значение `-ttl<…>` имени формы: `touch` | `wall` | секунды из сетки замера
369	/// В-74. Проверка та же, что у `--entry-ttl-secs` (`EntryTtl::parse`), иначе
370	/// имя формы описывало бы режим, которого сетка не знает.
371	fn parse_form_ttl(label: &str, value: &str) -> anyhow::Result<()> {
372	    let mode = match value {
373	        // У прежнего режима суффикса нет: `-ttltouch` — не имя, а другая
374	        // запись того же (как и `w1` у формы входа).
375	        "touch" => anyhow::bail!("{label}: прежний режим входа суффикса не несёт"),
376	        _ => value,
377	    };
378	    EntryTtl::parse(mode)
379	        .map(|_| ())
380	        .map_err(|e| anyhow::anyhow!("{label}: {e}"))
381	}
382	
383	/// Поле выхода имени формы (F7/F8): `none` — как раньше, `eat<X>` — выход по
384	/// съеданию стены, `gone<W>` — по снятию. Проверяются имена, которые сетка
385	/// пишет сама; произвольный хвост (`s1-t1-60-5`) — не имя. Список форм выхода
386	/// ведут F7/F8 — здесь читается то, что названо в плане 2026-09-20 §3 F7.
387	fn parse_form_exit(label: &str, value: &str) -> anyhow::Result<()> {
388	    if value == "none" {
389	        return Ok(());
390	    }
391	    let (prefix, number) = if let Some(rest) = value.strip_prefix("eat") {
392	        ("eat", rest)
393	    } else if let Some(rest) = value.strip_prefix("gone") {
394	        ("gone", rest)
395	    } else {
396	        anyhow::bail!(
397	            "{label}: выход {value:?} не из форм (`none`, `eat<X>` — съели, `gone<W>` — сняли)"
398	        );
399	    };
400	    let pct: f64 = number
401	        .parse()
402	        .map_err(|_| anyhow::anyhow!("{label}: {prefix}{number}: порог не число"))?;
403	    anyhow::ensure!(
404	        pct.is_finite() && pct > 0.0 && pct <= 100.0,
405	        "{label}: {prefix}{number}: порог — конечное число в (0, 100] %"
406	    );
407	    Ok(())
408	}
