410	/// Испытания **этой** процедуры в журнале — строки с префиксом `bounce_form`.
411	pub fn count_scoped_trials(rows: &[runs::RunRow], prefix: &str) -> usize {
412	    rows.iter()
413	        .filter(|r| r.kind.counts_as_trial() && r.detail.starts_with(prefix))
414	        .count()
415	}
