417	/// Ключ строки `forms.csv`.
418	#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
419	struct Cell {
420	    symbol: String,
421	    day: String,
422	    form: String,
423	}
424	
425	#[derive(Debug, Clone, Default)]
426	struct CellStat {
427	    n_signals: u64,
428	    /// Касаний, для которых форма не построилась (нет σ, фронтрана, второй
429	    /// плотности; В-65): `n_signals + n_skipped` — общее число касаний пары,
430	    /// одно у всех форм.
431	    n_skipped: u64,
432	    n_fills: u64,
433	    sum_net_bps: f64,
434	    exits: [u64; EXIT_REASONS.len()],
435	    /// Сигналы по часам UTC (`signals_by_hour` в `forms.csv`, В-60); `None` —
436	    /// столбца нет (дамп до 18.09) — вердикт по часам тогда невозможен.
437	    signals_by_hour: Option<[u64; 24]>,
438	}
