440	struct GridData {
441	    forms: Vec<String>,
442	    symbols: BTreeSet<String>,
443	    days: Vec<String>,
444	    cells: BTreeMap<Cell, CellStat>,
445	    /// `(net_bps, t0_ns)` кругов по (форма, сутки).
446	    fills: BTreeMap<(String, String), Vec<(f64, i64)>>,
447	}
