449	fn read_grid(dir: &Path) -> anyhow::Result<GridData> {
450	    let forms_path = dir.join("forms.csv");
451	    let rounds_path = dir.join("rounds.csv");
452	    let forms_text = std::fs::read_to_string(&forms_path)
453	        .with_context(|| format!("{}: forms.csv не читается", forms_path.display()))?;
454	    let mut r = csv::ReaderBuilder::new()
455	        .comment(Some(b'#'))
456	        .from_reader(forms_text.as_bytes());
457	    let header: Vec<String> = r.headers()?.iter().map(str::to_string).collect();
458	    let idx = |name: &str| -> anyhow::Result<usize> {
459	        header
460	            .iter()
461	            .position(|h| h == name)
462	            .ok_or_else(|| anyhow::anyhow!("{}: нет колонки {name}", forms_path.display()))
463	    };
464	    let (i_sym, i_day, i_form, i_sig, i_skipped, i_fills, i_sum) = (
465	        idx("symbol")?,
466	        idx("day_utc")?,
467	        idx("form")?,
468	        idx("n_signals")?,
469	        idx("n_skipped")?,
470	        idx("n_fills")?,
471	        idx("sum_net_bps")?,
472	    );
473	    let i_hours = header.iter().position(|h| h == "signals_by_hour");
474	    // Колонки причин выхода читаются **по наличию**: артефакты до F7/F8 их не
475	    // несут (`n_eaten_by_trades`/`n_wall_gone`), а вердикт обязан читаться по
476	    // уже снятой сетке — отсутствующая колонка это ноль, не отказ.
477	    let exit_idx: Vec<Option<usize>> = EXIT_REASONS
478	        .iter()
479	        .map(|r| header.iter().position(|h| h == &format!("n_{r}")))
480	        .collect();
481	    let mut cells: BTreeMap<Cell, CellStat> = BTreeMap::new();
482	    let mut form_set: BTreeSet<String> = BTreeSet::new();
483	    let mut symbols = BTreeSet::new();
484	    let mut days_set = BTreeSet::new();
485	    for rec in r.records() {
486	        let rec = rec?;
487	        let cell = Cell {
488	            symbol: rec[i_sym].to_string(),
489	            day: rec[i_day].to_string(),
490	            form: rec[i_form].to_string(),
491	        };
492	        parse_form(&cell.form)?;
493	        let signals_by_hour = match i_hours {
494	            Some(i) => {
495	                let parts: Vec<&str> = rec[i].split(':').collect();
496	                anyhow::ensure!(
497	                    parts.len() == 24,
498	                    "{}: signals_by_hour у {} {} {} — {} чисел, нужно 24",
499	                    forms_path.display(),
500	                    cell.symbol,
501	                    cell.day,
502	                    cell.form,
503	                    parts.len()
504	                );
505	                let mut h = [0u64; 24];
506	                for (k, v) in parts.iter().enumerate() {
507	                    h[k] = v.parse()?;
508	                }
509	                Some(h)
510	            }
511	            None => None,
512	        };
513	        let mut st = CellStat {
514	            n_signals: rec[i_sig].parse()?,
515	            n_skipped: rec[i_skipped].parse()?,
516	            n_fills: rec[i_fills].parse()?,
517	            sum_net_bps: rec[i_sum].parse()?,
518	            exits: [0; EXIT_REASONS.len()],
519	            signals_by_hour,
520	        };
521	        if let Some(h) = st.signals_by_hour {
522	            anyhow::ensure!(
523	                h.iter().sum::<u64>() == st.n_signals,
524	                "{}: signals_by_hour у {} {} {} не сходится с числом сигналов n_signals",
525	                forms_path.display(),
526	                cell.symbol,
527	                cell.day,
528	                cell.form
529	            );
530	        }
531	        for (k, &i) in exit_idx.iter().enumerate() {
532	            if let Some(i) = i {
533	                st.exits[k] = rec[i].parse()?;
534	            }
535	        }
536	        form_set.insert(cell.form.clone());
537	        symbols.insert(cell.symbol.clone());
538	        days_set.insert(cell.day.clone());
539	        anyhow::ensure!(
540	            cells.insert(cell.clone(), st).is_none(),
541	            "{}: строка {} {} {} повторяется",
542	            forms_path.display(),
543	            cell.symbol,
544	            cell.day,
545	            cell.form
546	        );
547	    }
548	    let grid_size = grid_size_from_labels(form_set.iter().map(String::as_str))?;
549	    anyhow::ensure!(
550	        form_set.len() == grid_size,
551	        "{}: форм {}, полная сетка В-62 по встреченным осям — {}; частичный прогон вердиктом не считается",
552	        forms_path.display(),
553	        form_set.len(),
554	        grid_size
555	    );
556	    // Полнота: у каждой пары (символ, сутки) все формы и одно число касаний
557	    // (`n_signals + n_no_sigma`: касания общие, сигналов у длинного окна `σ`
558	    // меньше — В-62).
559	    let mut by_pair: BTreeMap<(String, String), Vec<(&String, u64)>> = BTreeMap::new();
560	    for (c, st) in &cells {
561	        by_pair
562	            .entry((c.symbol.clone(), c.day.clone()))
563	            .or_default()
564	            .push((&c.form, st.n_signals.saturating_add(st.n_skipped)));
565	    }
566	    for ((sym, day), v) in &by_pair {
567	        anyhow::ensure!(
568	            v.len() == grid_size,
569	            "{sym} {day}: форм {}, нужно {} — сетка неполная",
570	            v.len(),
571	            grid_size
572	        );
573	        let sigs: BTreeSet<u64> = v.iter().map(|(_, n)| *n).collect();
574	        anyhow::ensure!(
575	            sigs.len() == 1,
576	            "{sym} {day}: число сигналов вместе с пропущенными касаниями расходится между формами {sigs:?} — касания должны быть общими"
577	        );
578	    }
579	
580	    let rounds_text = std::fs::read_to_string(&rounds_path)
581	        .with_context(|| format!("{}: rounds.csv не читается", rounds_path.display()))?;
582	    let mut r = csv::ReaderBuilder::new()
583	        .comment(Some(b'#'))
584	        .from_reader(rounds_text.as_bytes());
585	    let header: Vec<String> = r.headers()?.iter().map(str::to_string).collect();
586	    let idx = |name: &str| -> anyhow::Result<usize> {
587	        header
588	            .iter()
589	            .position(|h| h == name)
590	            .ok_or_else(|| anyhow::anyhow!("{}: нет колонки {name}", rounds_path.display()))
591	    };
592	    let (i_sym, i_day, i_form, i_net, i_t0) = (
593	        idx("symbol")?,
594	        idx("day_utc")?,
595	        idx("form")?,
596	        idx("net_bps")?,
597	        idx("t0_ns")?,
598	    );
599	    let mut fills: BTreeMap<(String, String), Vec<(f64, i64)>> = BTreeMap::new();
600	    let mut fills_per_cell: BTreeMap<Cell, u64> = BTreeMap::new();
601	    for rec in r.records() {
602	        let rec = rec?;
603	        let net: f64 = rec[i_net].parse().map_err(|_| {
604	            anyhow::anyhow!(
605	                "{}: круг {} {} {} без измеренного net ({}) — вердикт по неизмеренным кругам не считается",
606	                rounds_path.display(),
607	                &rec[i_sym],
608	                &rec[i_day],
609	                &rec[i_form],
610	                &rec[i_net]
611	            )
612	        })?;
613	        anyhow::ensure!(net.is_finite(), "{}: net не число", rounds_path.display());
614	        let cell = Cell {
615	            symbol: rec[i_sym].to_string(),
616	            day: rec[i_day].to_string(),
617	            form: rec[i_form].to_string(),
618	        };
619	        anyhow::ensure!(
620	            cells.contains_key(&cell),
621	            "{}: круг {} {} {} без строки в forms.csv",
622	            rounds_path.display(),
623	            cell.symbol,
624	            cell.day,
625	            cell.form
626	        );
627	        let t0_ns: i64 = rec[i_t0]
628	            .parse()
629	            .map_err(|_| anyhow::anyhow!("{}: t0_ns не число", rounds_path.display()))?;
630	        *fills_per_cell.entry(cell.clone()).or_default() += 1;
631	        fills
632	            .entry((cell.form, cell.day))
633	            .or_default()
634	            .push((net, t0_ns));
635	    }
636	    for (c, st) in &cells {
637	        let got = fills_per_cell.get(c).copied().unwrap_or(0);
638	        anyhow::ensure!(
639	            got == st.n_fills,
640	            "{} {} {}: кругов в rounds.csv {got}, в forms.csv {} — артефакты рассогласованы",
641	            c.symbol,
642	            c.day,
643	            c.form,
644	            st.n_fills
645	        );
646	    }
647	    Ok(GridData {
648	        forms: form_set.into_iter().collect(),
649	        symbols,
650	        days: days_set.into_iter().collect(),
651	        cells,
652	        fills,
653	    })
654	}
