656	fn day_index(days: &[String], day: &str) -> i64 {
657	    days.iter()
658	        .position(|d| d == day)
659	        .map(|i| i as i64)
660	        .unwrap_or(-1)
661	}
662	
663	fn form_verdict(data: &GridData, form: &str) -> anyhow::Result<FormVerdict> {
664	    let (stop, take, deadline_secs) = parse_form(form)?;
665	    let mut n_signals: u64 = 0;
666	    let mut n_fills: u64 = 0;
667	    let mut exits = [0u64; EXIT_REASONS.len()];
668	    let mut observations: Vec<FillObservation> = Vec::new();
669	    let mut returns: Vec<f64> = Vec::new();
670	    let mut days_with_fills: BTreeSet<&str> = BTreeSet::new();
671	    let mut clusters_with_fills: BTreeSet<i64> = BTreeSet::new();
672	    // В-60 (владелец 2026-09-18: «одного дня минимум хватает»): кластер —
673	    // сутки, когда суток в сетке не меньше `G_MIN`, иначе час UTC: у одних
674	    // суток 24 кластера, и бутстрэп Уэбба (`G_MIN` — его порог) работает.
675	    let by_hour = data.days.len() < G_MIN;
676	    let cluster_unit = if by_hour { "hour" } else { "day" };
677	    let hour_of =
678	        |t0_ns: i64| -> i64 { t0_ns.div_euclid(1_000_000_000).rem_euclid(86_400) / 3_600 };
679	    // Сигналы по часам суммируются **по суткам через все символы**: круги в
680	    // `data.fills` лежат по (форма, сутки) без символа, и сравнивать их с
681	    // сигналами одной ячейки нельзя (до 19.09 так и делалось — ложный отказ
682	    // «кругов больше сигналов» на первом же прогоне с двумя символами и
683	    // фильтром касаний; синтетика проходила случайно).
684	    let mut sig_hours_by_day: BTreeMap<&str, [u64; 24]> = BTreeMap::new();
685	    for (c, st) in data.cells.iter().filter(|(c, _)| c.form == form) {
686	        n_signals = n_signals.saturating_add(st.n_signals);
687	        n_fills = n_fills.saturating_add(st.n_fills);
688	        for (k, e) in st.exits.iter().enumerate() {
689	            exits[k] = exits[k].saturating_add(*e);
690	        }
691	        let day = day_index(&data.days, &c.day);
692	        if by_hour {
693	            let Some(sig_by_hour) = st.signals_by_hour else {
694	                anyhow::bail!(
695	                    "{} {} {}: forms.csv без signals_by_hour — вердикт по часам (суток меньше {G_MIN}) \
696	                     невозможен; дамп сделан сеткой до 18.09, пересчитать `lob bounce-grid`",
697	                    c.symbol,
698	                    c.day,
699	                    c.form
700	                );
701	            };
702	            let acc = sig_hours_by_day.entry(c.day.as_str()).or_insert([0; 24]);
703	            for h in 0..24 {
704	                acc[h] = acc[h].saturating_add(sig_by_hour[h]);
705	            }
706	            if st.n_fills > 0 {
707	                days_with_fills.insert(c.day.as_str());
708	            }
709	            continue;
710	        }
711	        let cluster = day;
712	        let nets = data
713	            .fills
714	            .get(&(c.form.clone(), c.day.clone()))
715	            .map(Vec::as_slice)
716	            .unwrap_or(&[]);
717	        // Круги этой ячейки — первые `st.n_fills` ещё не отданных кругов пары
718	        // (форма, сутки): порядок внутри суток вердикту не важен, интервал
719	        // считается по суммам суток.
720	        if st.n_fills > 0 {
721	            days_with_fills.insert(c.day.as_str());
722	        }
723	        for _ in 0..st.n_signals.saturating_sub(st.n_fills) {
724	            observations.push(FillObservation {
725	                day_cluster: cluster,
726	                net_bps: 0.0,
727	                filled: false,
728	            });
729	        }
730	        let _ = nets;
731	    }
732	    if by_hour {
733	        for (day_label, sig_by_hour) in &sig_hours_by_day {
734	            let day = day_index(&data.days, day_label);
735	            let day_fills = data
736	                .fills
737	                .get(&(form.to_string(), (*day_label).to_string()))
738	                .map(Vec::as_slice)
739	                .unwrap_or(&[]);
740	            let mut fills_by_hour = [0u64; 24];
741	            for &(_, t0) in day_fills {
742	                fills_by_hour[hour_of(t0) as usize] += 1;
743	            }
744	            for h in 0..24 {
745	                anyhow::ensure!(
746	                    fills_by_hour[h] <= sig_by_hour[h],
747	                    "{form} {day_label}: в часе {h} кругов {} больше сигналов {} (сумма по символам)",
748	                    fills_by_hour[h],
749	                    sig_by_hour[h]
750	                );
751	                let cluster = day * 24 + h as i64;
752	                for _ in 0..(sig_by_hour[h] - fills_by_hour[h]) {
753	                    observations.push(FillObservation {
754	                        day_cluster: cluster,
755	                        net_bps: 0.0,
756	                        filled: false,
757	                    });
758	                }
759	            }
760	        }
761	    }
762	    for ((f, day), nets) in data.fills.iter().filter(|((f, _), _)| f == form) {
763	        let d = day_index(&data.days, day);
764	        for &(net, t0) in nets {
765	            let cluster = if by_hour { d * 24 + hour_of(t0) } else { d };
766	            clusters_with_fills.insert(cluster);
767	            observations.push(FillObservation {
768	                day_cluster: cluster,
769	                net_bps: net,
770	                filled: true,
771	            });
772	            returns.push(net);
773	        }
774	        let _ = f;
775	    }
776	    let interval = if n_fills == 0 {
777	        None
778	    } else {
779	        net_fill_interval(&observations, GATE_ALPHA, BOOTSTRAP_REPLICATIONS, 0)
780	    };
781	    let net_per_fill_bps = if returns.is_empty() {
782	        None
783	    } else {
784	        Some(returns.iter().sum::<f64>() / crate::stats::count_f64(returns.len()))
785	    };
786	    Ok(FormVerdict {
787	        form: form.to_string(),
788	        stop,
789	        take,
790	        deadline_secs,
791	        n_signals,
792	        n_fills,
793	        days_with_fills: days_with_fills.len(),
794	        cluster_unit,
795	        clusters_with_fills: clusters_with_fills.len(),
796	        interval,
797	        net_per_fill_bps,
798	        sharpe: final_metrics::sharpe_ratio(&returns),
799	        exits,
800	        returns,
801	    })
802	}
803	
804	/// Матрица «форма × сутки»: ячейка — `net_fill` формы за сутки по всем
805	/// символам (сумма `net` кругов на число сигналов), как у `net_fill_interval`.
806	fn form_day_matrix(data: &GridData) -> Vec<Vec<f64>> {
807	    data.forms
808	        .iter()
809	        .map(|form| {
810	            data.days
811	                .iter()
812	                .map(|day| {
813	                    let mut sum = 0.0;
814	                    let mut sigs: u64 = 0;
815	                    for (_c, st) in data
816	                        .cells
817	                        .iter()
818	                        .filter(|(c, _)| &c.form == form && &c.day == day)
819	                    {
820	                        sum += st.sum_net_bps;
821	                        sigs = sigs.saturating_add(st.n_signals);
822	                    }
823	                    if sigs == 0 {
824	                        f64::NAN
825	                    } else {
826	                        sum / crate::stats::count_f64_u64(sigs)
827	                    }
828	                })
829	                .collect()
830	        })
