834	fn verdict_of(best: &FormVerdict, dsr: Option<f64>) -> Verdict {
835	    // В-60: хотя бы одни сутки с кругами и `G_MIN` кластеров (суток или часов).
836	    if best.n_fills < CONFIRM_MIN_N || best.days_with_fills < 1 || best.clusters_with_fills < G_MIN
837	    {
838	        return Verdict::NotEnoughData;
839	    }
840	    let Some(iv) = best.interval.as_ref() else {
841	        return Verdict::NotEnoughData;
842	    };
843	    let dsr_ok = dsr.is_some_and(|d| d >= DSR_TARGET);
844	    if iv.lower_bps <= 0.0 || !dsr_ok {
845	        Verdict::Red
846	    } else if iv.point_bps < GREEN_NET_BPS {
847	        Verdict::GreenNoCapacity
848	    } else {
849	        Verdict::Green
850	    }
851	}
